{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "A high proportion of SARS-CoV-2 patients survive infection but the prevalence of chronic sequelae and resulting disability is increasing... To date, the ClinicalTrials.gov website 2 of the National Library of Medicine has registered more than 6400 clinical studies targeting the epidemiology and management of COVID-19, but only 245 studies (188 of which are ongoing) address rehabilitation in COVID-19 survivors. ... Most studies provided low-level descriptive evidence",
      "reason": "The introduction describes the current state of knowledge (growing chronic sequelae/disability, predominance of low-level descriptive evidence, few rehabilitation studies) and highlights uncertainties such as the lack of high-quality intervention studies."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "The best available research evidence is required to inform management and rehabilitation decisions, interventions, and health systems for COVID-19 survivors with adverse clinical sequelae. Further evidence is warranted to estimate the resources needed to plan for setting appropriate and adequately delivered post-acute and long-term rehabilitation services.",
      "reason": "The need and importance of the review are explicitly explained: best evidence is required to inform rehabilitation decisions and service planning for COVID-19 survivors."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "The methodology of this systematic review updates the second edition published in June 2020. 4",
      "reason": "As an update (third edition) of an existing living review, the manuscript identifies and cites the previous review editions (second edition cited with reference 4) and explains the reason for updating (new analytical studies enabling critical appraisal, longer follow-up data)."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The review includes studies on intervention effectiveness (five intervention studies, three RCTs), but no proposed mechanism of action of rehabilitation interventions is described anywhere in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "Rehabilitation for COVID-19 is a complex intervention delivered across multiple phases and settings, but no logic model or hypothesized relationships between intervention components and outcomes is reported in the retrieved evidence."
    }
  ],
  "confidence": 82
}

{
